return {
  bonus: {
    hook: "attackDamage", aura: true, group: "spear.t1.decoy",
    run(H, actor, ctx) {
      const lane = { "Ranged Left": "Flank Left", "Ranged Front": "Front", "Ranged Right": "Flank Right" };
      const zone = lane[ctx.attackerZone];
      if (!zone) return;
      const carrier = H.zone.huntersIn(zone).some(h => h.id !== actor.id
        && ctx.carrierIds.includes(h.id));
      return carrier ? { resolve: 1, wounds: 1 } : null;
    },
  },
};
